const crypto = require('crypto');
const fs = require('fs');

const input = $input.first();
const rawBody = Buffer.from(input.binary.data.data, 'base64');
const payload = JSON.parse(rawBody.toString('utf8'));
const directory = '/home/node/.n8n/notion-events';
const tokenPath = `${directory}/verification-token`;

fs.mkdirSync(directory, { recursive: true });

if (payload.verification_token) {
  fs.writeFileSync(tokenPath, payload.verification_token, { mode: 0o600 });
  return [{ json: { verification_received: true } }];
}

if (!fs.existsSync(tokenPath)) throw new Error('Notion webhook verification token is missing');
const verificationToken = fs.readFileSync(tokenPath, 'utf8').trim();
const receivedSignature = input.json.headers['x-notion-signature'] || '';
const expectedSignature = `sha256=${crypto.createHmac('sha256', verificationToken).update(rawBody).digest('hex')}`;
const valid = receivedSignature.length === expectedSignature.length &&
  crypto.timingSafeEqual(Buffer.from(receivedSignature), Buffer.from(expectedSignature));
if (!valid) throw new Error('Invalid Notion webhook signature');

const allowedTypes = new Set([
  'page.created',
  'page.content_updated',
  'page.properties_updated',
  'page.moved',
  'page.deleted',
  'page.undeleted',
  'database.created',
  'database.moved',
  'database.deleted',
  'database.undeleted',
  'data_source.created',
  'data_source.content_updated',
  'data_source.schema_updated',
  'data_source.moved',
  'data_source.deleted',
  'data_source.undeleted'
]);
if (!allowedTypes.has(payload.type)) return [{ json: { ignored: true, type: payload.type } }];

const event = {
  schema_version: 1,
  event_id: payload.id,
  timestamp: payload.timestamp,
  received_at: new Date().toISOString(),
  type: payload.type,
  api_version: payload.api_version || null,
  workspace_id: payload.workspace_id,
  workspace_name: payload.workspace_name || null,
  subscription_id: payload.subscription_id || null,
  integration_id: payload.integration_id || null,
  entity_id: payload.entity?.id || null,
  entity_type: payload.entity?.type || null,
  parent_id: payload.data?.parent?.id || null,
  parent_type: payload.data?.parent?.type || null,
  authors: payload.authors || [],
  attempt_number: payload.attempt_number || 1,
  data: payload.data || {}
};
fs.appendFileSync(`${directory}/events.jsonl`, `${JSON.stringify(event)}\n`, { mode: 0o600 });
return [{ json: { logged: true, event_id: event.event_id, type: event.type } }];
